package escuela.personal.controller;
import escuela.personal.dto.*;
import escuela.personal.service.*;
import escuela.admin.dto.ResultadoAutocompletado;
import escuela.admin.support.MensajeErrorFormulario;
import escuela.common.exception.ReglaNegocioException;
import lombok.RequiredArgsConstructor;
import jakarta.validation.Valid;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import java.util.*;
import java.io.IOException;

@Controller @RequiredArgsConstructor @RequestMapping("/admin/preparacion-nomina/{idNomina}/pagos")
public class PagoEmpleadoNominaController {
 private final PagoEmpleadoNominaService service;
 private final PagoMultipleNominaService multiples;
 private final PreparacionNominaService preparacion;
 private final EmpleadoService empleados;
 private String ruta(Long id){return "/admin/preparacion-nomina/"+id+"/pagos";}
 private void base(Long id,FiltroNomina origen,FiltroPagoNomina filtro,Model m){m.addAttribute("filtro",origen.normalizado());m.addAttribute("pagoFiltro",filtro.normalizado());m.addAttribute("borrador",preparacion.obtener(id));m.addAttribute("rutaPagos",ruta(id));m.addAttribute("volverUrl",filtro.url(origen,ruta(id)));m.addAttribute("puedeEditar",empleados.permitido("CONDICION_SALARIAL_ADMINISTRAR"));m.addAttribute("puedePagar",service.puedePagar());m.addAttribute("puedeRevertir",service.puedeRevertir());m.addAttribute("autorizada",service.autorizada(id));}
 @GetMapping String listado(@PathVariable("idNomina")Long id,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){if(preparacion.obtener(id).estado().equals("APLICADA"))return "redirect:"+origen.url("/admin/preparacion-nomina/"+id);base(id,origen,filtro,m);if(!m.containsAttribute("cancelacionForm"))m.addAttribute("cancelacionForm",new PagoEmpleadoNominaForm());var f=filtro.normalizado();m.addAttribute("resultado",service.listar(id,f.buscarPago(),f.estadoPago(),f.paginaPago(),f.tamanioPago()));m.addAttribute("resumenPagos",service.resumen(id));if(service.puedeRevertir())m.addAttribute("cuentasCancelar",service.cuentasCancelar(id));return "admin/nomina-pagos";}
 @PostMapping("/autorizar") String autorizar(@PathVariable("idNomina")Long id,@RequestParam Long version,@RequestParam String motivo,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){try{service.autorizar(id,version,motivo);m.addAttribute("mensaje","Revisión autorizada y congelada. Todavía no se pagó a nadie ni se abonó a préstamos.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));m.addAttribute("motivoCapturado",motivo);}return listado(id,origen,filtro,m);}
 @PostMapping("/cancelar-todos") String cancelarTodos(@PathVariable("idNomina")Long id,@ModelAttribute PagoEmpleadoNominaForm form,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){try{service.cancelarTodos(id,form);m.addAttribute("mensaje","Pagos cancelados: cada importe volvió a su cuenta original. Los empleados quedan pendientes para pago individual del mismo periodo.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}m.addAttribute("cancelacionForm",form);return listado(id,origen,filtro,m);}
 @GetMapping("/{fila:\\d+}") String detalle(@PathVariable("idNomina")Long id,@PathVariable Long fila,@RequestParam(defaultValue="0")int paginaIntentos,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){if(preparacion.obtener(id).estado().equals("APLICADA"))return "redirect:"+origen.url("/admin/preparacion-nomina/"+id);var r=service.fila(id,fila);base(id,origen,filtro,m);m.addAttribute("empleadoPago",r);m.addAttribute("cuotas",service.cuotas(id,fila));m.addAttribute("intentos",service.historial(id,fila,paginaIntentos));if(service.puedePagar())m.addAttribute("fuentesPago",multiples.fuentes(id,fila));if(!m.containsAttribute("formPago")){var f=new PagoEmpleadoNominaForm();f.setVersion(preparacion.obtener(id).version());m.addAttribute("formPago",f);}return "admin/nomina-pago-empleado";}
 @PostMapping("/{fila:\\d+}/revisar") String revisar(@PathVariable("idNomina")Long id,@PathVariable Long fila,@Valid @ModelAttribute("formPago")PagoEmpleadoNominaForm f,BindingResult errores,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){if(!errores.hasErrors())try{m.addAttribute("vistaPago",service.revisar(id,fila,f));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());}if(errores.hasErrors())m.addAttribute("errorOperacion","Revisa referencia y motivo. La captura permanece en pantalla.");m.addAttribute("pagoTab","gestion");return detalle(id,fila,0,origen,filtro,m);}
 @PostMapping("/{fila:\\d+}/pagar") String pagar(@PathVariable("idNomina")Long id,@PathVariable Long fila,@Valid @ModelAttribute("formPago")PagoEmpleadoNominaForm f,BindingResult errores,@RequestParam String sello,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){if(!errores.hasErrors())try{service.pagar(id,fila,f,sello);m.addAttribute("mensaje","Pago individual registrado. Sólo sus cuotas de préstamo fueron abonadas; los demás empleados no cambiaron.");m.asMap().remove(org.springframework.validation.BindingResult.MODEL_KEY_PREFIX+"formPago");m.asMap().remove("formPago");m.addAttribute("pagoTab","historial");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Completa los datos y confirma la salida real.");return detalle(id,fila,0,origen,filtro,m);}
 @PostMapping("/{fila:\\d+}/rechazar") String rechazar(@PathVariable("idNomina")Long id,@PathVariable Long fila,@Valid @ModelAttribute("formPago")PagoEmpleadoNominaForm f,BindingResult errores,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){if(!errores.hasErrors())try{service.rechazar(id,fila,f);m.addAttribute("mensaje","Rechazo registrado SIN salida de dinero. Sigue pendiente y no se abonó a préstamos.");m.asMap().remove(org.springframework.validation.BindingResult.MODEL_KEY_PREFIX+"formPago");m.asMap().remove("formPago");m.addAttribute("pagoTab","historial");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Captura referencia y motivo del rechazo.");return detalle(id,fila,0,origen,filtro,m);}
 @PostMapping("/{fila:\\d+}/revertir/{pago}") String revertir(@PathVariable("idNomina")Long id,@PathVariable Long fila,@PathVariable Long pago,@Valid @ModelAttribute("formPago")PagoEmpleadoNominaForm f,BindingResult errores,@ModelAttribute FiltroNomina origen,@ModelAttribute FiltroPagoNomina filtro,Model m){if(!errores.hasErrors())try{service.revertir(id,fila,pago,f);m.addAttribute("mensaje","Reversa individual registrada. El dinero regresó a la cuenta original, los abonos se compensaron y este empleado vuelve a pendiente.");m.asMap().remove(org.springframework.validation.BindingResult.MODEL_KEY_PREFIX+"formPago");m.asMap().remove("formPago");m.addAttribute("pagoTab","historial");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException e){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(e));}if(errores.hasErrors())m.addAttribute("errorOperacion","Captura el motivo, referencia y confirma la devolución real.");return detalle(id,fila,0,origen,filtro,m);}
 @GetMapping("/cuentas") @ResponseBody ResponseEntity<ResultadoAutocompletado> cuentas(@PathVariable("idNomina")Long id,@RequestParam(defaultValue="")String q){var r=service.cuentas(id,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(r.stream().limit(10).toList(),r.size()>10));}
 @GetMapping("/motivos") @ResponseBody ResponseEntity<ResultadoAutocompletado> motivos(@PathVariable("idNomina")Long id,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="false")boolean reversa){var r=service.motivos(id,q,reversa);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(r.stream().limit(10).toList(),r.size()>10));}
 @GetMapping("/excel") void excel(@PathVariable("idNomina")Long id,@ModelAttribute FiltroPagoNomina original,HttpServletResponse response)throws IOException{var f=original.normalizado();service.listar(id,f.buscarPago(),f.estadoPago(),0,100);response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");response.setHeader("Content-Disposition","attachment; filename=pagos-nomina.xlsx");response.setHeader("Cache-Control","no-store");try(var b=new org.apache.poi.xssf.streaming.SXSSFWorkbook(100)){try{var s=b.createSheet("Pagos por empleado");String[] cab={"Código","Empleado","Neto autorizado","Moneda","Estado actual","Pago vigente"};var h=s.createRow(0);for(int n=0;n<cab.length;n++){h.createCell(n).setCellValue(cab[n]);s.setColumnWidth(n,30*256);}var dinero=b.createCellStyle();dinero.setDataFormat(b.createDataFormat().getFormat("\"$\"#,##0.00"));int row=1,pag=0;boolean mas;do{var page=service.listar(id,f.buscarPago(),f.estadoPago(),pag++,100);mas=page.hasNext();for(var e:page){var r=s.createRow(row++);r.createCell(0).setCellValue(e.codigo());r.createCell(1).setCellValue(e.nombre());r.createCell(2).setCellValue(e.neto().doubleValue());r.getCell(2).setCellStyle(dinero);r.createCell(3).setCellValue(e.moneda());r.createCell(4).setCellValue(e.estado());r.createCell(5).setCellValue(e.pagoId()==null?"":"NPI-"+e.pagoId());}}while(mas);s.createFreezePane(0,1);b.write(response.getOutputStream());}finally{b.dispose();}}}
}
